const acorn=require('acorn');
const {JSDOM,VirtualConsole}=require('jsdom');

const repo=process.env.GH_REPOSITORY,token=process.env.GH_TOKEN,path='siza-mobile-test/index.html';
const headers={'Accept':'application/vnd.github+json','Authorization':`Bearer ${token}`,'X-GitHub-Api-Version':'2022-11-28'};
const api=`https://api.github.com/repos/${repo}/contents/${path}`;
const assert=(v,m)=>{if(!v)throw new Error(m)};
async function getFile(p){const r=await fetch(`https://api.github.com/repos/${repo}/contents/${p}?ref=main`,{headers});if(!r.ok)throw new Error(`${p}: GET ${r.status}`);const f=await r.json();return{sha:f.sha,text:Buffer.from(f.content.replace(/\n/g,''),'base64').toString('utf8')}}
function parse(html){const so=html.lastIndexOf('<script>'),sc=html.indexOf('</script>',so);assert(so>=0&&sc>so,'main script not found');const start=so+8,code=html.slice(start,sc),ast=acorn.parse(code,{ecmaVersion:'latest'}),decl=[];function walk(n){if(!n||typeof n!=='object')return;if(n.type==='FunctionDeclaration'&&n.id)decl.push(n);for(const[k,v]of Object.entries(n)){if(k==='start'||k==='end')continue;if(Array.isArray(v))v.forEach(walk);else if(v&&typeof v==='object'&&v.type)walk(v)}}walk(ast);return{start,sc,code,decl}}
function replaceFn(html,name,replacement){const p=parse(html),nodes=p.decl.filter(n=>n.id.name===name);assert(nodes.length===1,`${name}: expected 1 declaration, got ${nodes.length}`);const n=nodes[0],code=p.code.slice(0,n.start)+replacement+p.code.slice(n.end);return html.slice(0,p.start)+code+html.slice(p.sc)}
function inlineCore(html,files){let out=html;for(const[name,text]of [['card-effects.js',files.effects],['card-schema.js',files.schema],['cards.js',files.cards],['card-renderer.js',files.renderer]]){const tag=`<script src="../siza-core/${name}"></script>`;assert(out.includes(tag),`Missing core tag ${name}`);out=out.replace(tag,`<script>${text}</script>`)}return out}
function makeDom(html,label){const vc=new VirtualConsole();vc.on('jsdomError',e=>console.error(`[JSDOM ${label}]`,e.message));return new JSDOM(html,{runScripts:'dangerously',url:'https://siza.local/siza-mobile-test/',virtualConsole:vc})}
const replacement="function removeBattlefieldAt(P,i,dest='graveyard'){const M=state.match;if(i<0||i>=P.battlefield.length)return null;const id=P.battlefield.splice(i,1)[0];P[dest].push(id);P.powerCounters.splice(i,1);P.summonedOn.splice(i,1);P.exhausted=(P.exhausted||[]).filter(x=>x!==i).map(x=>x>i?x-1:x);for(const e of P.equipment||[]){if(e.target===i)e.target=null;else if(e.target>i)e.target--}if(M?.player===P&&M.ui){M.ui.attackers=(M.ui.attackers||[]).filter(x=>x!==i).map(x=>x>i?x-1:x);if(M.ui.creature===i)M.ui.creature=-1;else if(M.ui.creature>i)M.ui.creature--;const F=M.ui.fieldFocus;if(F?.owner==='player'){if(F.index===i)M.ui.fieldFocus=null;else if(F.index>i)F.index--}}if(M?.enemy===P&&M.ui?.fieldFocus?.owner==='enemy'){if(M.ui.fieldFocus.index===i)M.ui.fieldFocus=null;else if(M.ui.fieldFocus.index>i)M.ui.fieldFocus.index--}return id}";

(async()=>{
 const index=await getFile(path),files={effects:(await getFile('siza-core/card-effects.js')).text,schema:(await getFile('siza-core/card-schema.js')).text,cards:(await getFile('siza-core/cards.js')).text,renderer:(await getFile('siza-core/card-renderer.js')).text};console.log('Current Mobile blob '+index.sha);
 const p=parse(index.text),nodes=p.decl.filter(n=>n.id.name==='removeBattlefieldAt');assert(nodes.length===1,'removeBattlefieldAt must be canonical before repair');const current=p.code.slice(nodes[0].start,nodes[0].end);assert(!current.includes('M.ui.attackers'),'UI index repair already present; refusing duplicate patch');
 const html=replaceFn(index.text,'removeBattlefieldAt',replacement);const marker='window.SIZA={';assert(index.text.includes(marker)&&html.includes(marker),'SIZA marker missing');const probe=`window.__UI_INDEX_TEST__={createMatch,setMatch:m=>state.match=m,removeBattlefieldAt};\n`;
 const oldDom=makeDom(inlineCore(index.text,files).replace(marker,probe+marker),'old'),newDom=makeDom(inlineCore(html,files).replace(marker,probe+marker),'new');oldDom.window.setTimeout=()=>0;newDom.window.setTimeout=()=>0;
 function setup(dom){const H=dom.window.__UI_INDEX_TEST__,M=H.createMatch(false,'prepare');H.setMatch(M);const P=M.player;P.hand=[];P.graveyard=[];P.battlefield=['servitor','ignimite','watcher'];P.powerCounters=[0,1,0];P.summonedOn=[1,1,1];P.exhausted=[1,2];P.equipment=[{id:'tideblade',target:2}];M.ui={hand:-1,creature:2,attackMode:true,attackers:[1,2],fieldFocus:{owner:'player',index:2}};return{H,M,P}}
 const o=setup(oldDom);o.H.removeBattlefieldAt(o.P,0,'hand');assert(o.M.ui.creature===2&&JSON.stringify(o.M.ui.attackers)==='[1,2]'&&o.M.ui.fieldFocus.index===2,'Bug precondition no longer reproduced');console.log('PASS old runtime reproduces stale player UI indices');
 const n=setup(newDom);const removed=n.H.removeBattlefieldAt(n.P,0,'hand');assert(removed==='servitor'&&n.P.hand[0]==='servitor'&&n.M.ui.creature===1&&JSON.stringify(n.M.ui.attackers)==='[0,1]'&&n.M.ui.fieldFocus.index===1&&n.P.equipment[0].target===1&&JSON.stringify(n.P.exhausted)==='[0,1]','Player UI indices were not repaired correctly');console.log('PASS player UI indices shift with battlefield');
 n.M.ui={hand:-1,creature:0,attackMode:true,attackers:[0,1],fieldFocus:{owner:'player',index:0}};n.P.battlefield=['servitor','watcher'];n.P.powerCounters=[0,0];n.P.summonedOn=[1,1];n.P.exhausted=[];n.P.equipment=[];n.P.hand=[];n.P.graveyard=[];n.H.removeBattlefieldAt(n.P,0,'graveyard');assert(n.M.ui.creature===-1&&JSON.stringify(n.M.ui.attackers)==='[0]'&&n.M.ui.fieldFocus===null,'Removed focused creature did not clear/remap player UI');console.log('PASS removed player creature clears focus and selection');
 const E=n.M.enemy;E.battlefield=['servitor','watcher'];E.powerCounters=[0,0];E.summonedOn=[1,1];E.exhausted=[];E.equipment=[];E.hand=[];E.graveyard=[];n.M.ui.fieldFocus={owner:'enemy',index:1};n.H.removeBattlefieldAt(E,0,'graveyard');assert(n.M.ui.fieldFocus?.owner==='enemy'&&n.M.ui.fieldFocus.index===0,'Enemy focus index did not shift');n.H.removeBattlefieldAt(E,0,'graveyard');assert(n.M.ui.fieldFocus===null,'Enemy focus did not clear when focused creature left');console.log('PASS enemy focus indices shift and clear');
 const core=newDom.window.SIZA.runArenaCriticalV071();assert(core.passed===core.total,'Arena '+core.passed+'/'+core.total);console.log('PASS Arena '+core.passed+'/'+core.total);oldDom.window.close();newDom.window.close();
 const w=await fetch(api,{method:'PUT',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify({message:'Repair battlefield UI indices after creature removal',content:Buffer.from(html,'utf8').toString('base64'),sha:index.sha,branch:'main'})});if(!w.ok)throw new Error(`PUT ${w.status}: ${await w.text()}`);const out=await w.json();console.log('COMMIT '+out.commit.sha);
})().catch(e=>{console.error(e.stack||e.message);process.exit(1)});
